// src/App.js
import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [resumes, setResumes] = useState([]);
  const [jobDescription, setJobDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [jobTitle, setJobTitle] = useState('');

  // Configure axios base URL (update if your backend runs on different port)
  const API_BASE_URL = 'http://localhost:8000';
  axios.defaults.baseURL = API_BASE_URL;

  // Upload and parse resume
  const uploadResume = async (file) => {
    if (!file) {
      alert('Please select a file first');
      return;
    }

    const formData = new FormData();
    formData.append('file', file);

    setLoading(true);
    try {
      const response = await axios.post('/upload-resume/', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      // Add the resume data to the list
      setResumes([...resumes, { ...response.data, id: Date.now() }]);
      alert('Resume uploaded and parsed successfully!');
      setSelectedFile(null);
    } catch (error) {
      console.error('Upload error:', error);
      alert('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  // Match resume with job
  const matchResume = async (resumeId) => {
    if (!jobDescription.trim()) {
      alert('Please add a job description first');
      return;
    }

    setLoading(true);
    try {
      // First, save the job description
      const jobResponse = await axios.post('/save-job/', {
        title: jobTitle || 'Untitled Position',
        description: jobDescription,
        requirements: jobDescription // You can modify this to extract requirements
      });

      const jobId = jobResponse.data.job_id;

      // Then match the resume
      const matchResponse = await axios.post('/match-resume/', {
        resume_id: resumeId,
        job_id: jobId
      });

      // Update the resume with match score
      setResumes(resumes.map(resume => 
        resume.id === resumeId 
          ? { ...resume, 
              match_score: matchResponse.data.match_score,
              justification: matchResponse.data.justification,
              matched_skills: matchResponse.data.matched_skills,
              missing_skills: matchResponse.data.missing_skills
            }
          : resume
      ));

    } catch (error) {
      console.error('Match error:', error);
      alert('Failed to match resume: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  // Get shortlisted candidates
  const getShortlisted = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/shortlisted/?min_score=7');
      setResumes(response.data);
    } catch (error) {
      console.error('Error fetching shortlisted:', error);
      alert('Failed to fetch shortlisted candidates');
    } finally {
      setLoading(false);
    }
  };

  // Handle file selection
  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const validTypes = ['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
      if (!validTypes.includes(file.type)) {
        alert('Please upload a PDF or DOCX file');
        return;
      }
      setSelectedFile(file);
    }
  };

  // Handle file upload button click
  const handleUpload = () => {
    if (selectedFile) {
      uploadResume(selectedFile);
    } else {
      alert('Please select a file');
    }
  };

  // Candidate Card Component
  const CandidateCard = ({ resume }) => (
    <div className="candidate-card">
      <h3>{resume.name || `Candidate ${resume.id}`}</h3>
      {resume.match_score && (
        <div className="match-score">
          <span className="score">Match Score: {resume.match_score}/10</span>
        </div>
      )}
      {resume.justification && (
        <div className="justification">
          <strong>Justification:</strong> {resume.justification}
        </div>
      )}
      {resume.skills && resume.skills.length > 0 && (
        <div className="skills">
          <strong>Skills:</strong> {resume.skills.join(', ')}
        </div>
      )}
      {resume.experience && (
        <div className="experience">
          <strong>Experience:</strong> {resume.experience}
        </div>
      )}
      {resume.education && (
        <div className="education">
          <strong>Education:</strong> {resume.education}
        </div>
      )}
      {resume.matched_skills && resume.matched_skills.length > 0 && (
        <div className="matched-skills">
          <strong style={{ color: 'green' }}>✅ Matched Skills:</strong> {resume.matched_skills.join(', ')}
        </div>
      )}
      {resume.missing_skills && resume.missing_skills.length > 0 && (
        <div className="missing-skills">
          <strong style={{ color: 'red' }}>❌ Missing Skills:</strong> {resume.missing_skills.join(', ')}
        </div>
      )}
      {!resume.match_score && (
        <button 
          onClick={() => matchResume(resume.id)}
          className="match-btn"
          disabled={loading}
        >
          Match with Job
        </button>
      )}
    </div>
  );

  return (
    <div className="App">
      <header className="app-header">
        <h1>🤖 Smart Resume Screener</h1>
        <p>Upload resumes and match them with job descriptions using AI</p>
      </header>

      <div className="container">
        <div className="left-panel">
          {/* Job Description Input */}
          <div className="section">
            <h2>📋 Job Description</h2>
            <input
              type="text"
              placeholder="Job Title"
              value={jobTitle}
              onChange={(e) => setJobTitle(e.target.value)}
              className="job-title-input"
            />
            <textarea
              placeholder="Paste job description here..."
              value={jobDescription}
              onChange={(e) => setJobDescription(e.target.value)}
              rows="6"
              className="job-description-input"
            />
            <button onClick={() => alert('Job saved!')} className="save-job-btn">
              Save Job Description
            </button>
          </div>

          {/* Resume Upload */}
          <div className="section">
            <h2>📄 Upload Resume</h2>
            <div className="upload-area">
              <input
                type="file"
                accept=".pdf,.docx"
                onChange={handleFileChange}
                className="file-input"
                id="file-upload"
              />
              <label htmlFor="file-upload" className="file-label">
                {selectedFile ? selectedFile.name : 'Choose a PDF or DOCX file'}
              </label>
              <button 
                onClick={handleUpload}
                className="upload-btn"
                disabled={loading || !selectedFile}
              >
                {loading ? 'Uploading...' : 'Upload Resume'}
              </button>
            </div>
          </div>

          {/* Actions */}
          <div className="section">
            <button onClick={getShortlisted} className="shortlist-btn" disabled={loading}>
              🏆 Get Shortlisted Candidates
            </button>
          </div>
        </div>

        <div className="right-panel">
          <h2>📊 Candidates</h2>
          <div className="candidates-list">
            {resumes.length === 0 ? (
              <p className="no-candidates">No resumes uploaded yet. Upload a resume to get started!</p>
            ) : (
              resumes.map((resume, index) => (
                <CandidateCard key={resume.id || index} resume={resume} />
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
